//! `app calc`: 64-bit integer expression evaluator. See the `calc` section of SPEC.md.
//!
//! Each line is parsed and evaluated in a single pass by an operator-precedence
//! (shunting-yard) parser that keeps explicit operand and operator stacks. Unlike
//! a recursive-descent parser, its native stack usage does not grow with nesting
//! depth, so pathological inputs such as a million `(` or `-` cannot overflow it.

use std::fmt;
use std::io::{self, BufRead, Write};

/// Entry point for `app calc`: reads `input` to completion and writes the
/// result to `output`. The caller flushes `output`.
pub fn run<R: BufRead, W: Write>(mut input: R, mut output: W) -> io::Result<()> {
    let mut evaluator = Evaluator::default();
    let mut line = Vec::new();

    loop {
        line.clear();
        if input.read_until(b'\n', &mut line)? == 0 {
            return Ok(());
        }
        let expr = line.strip_suffix(b"\n").unwrap_or(&line);
        if expr.iter().all(|&b| is_blank(b)) {
            continue;
        }
        match evaluator.eval(expr) {
            Ok(value) => writeln!(output, "{value}")?,
            Err(_) => output.write_all(b"error\n")?,
        }
    }
}

/// Why an expression has no value.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Error {
    /// The input does not match the grammar.
    Syntax,
    /// Division or remainder by zero.
    DivisionByZero,
    /// A literal or an intermediate result is outside the `i64` range.
    Overflow,
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(match self {
            Error::Syntax => "syntax error",
            Error::DivisionByZero => "division by zero",
            Error::Overflow => "overflow",
        })
    }
}

impl std::error::Error for Error {}

/// An entry of the operator stack.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Op {
    Add,
    Sub,
    Mul,
    Div,
    Rem,
    Neg,
    /// An open parenthesis: a barrier that reductions never cross.
    LParen,
}

impl Op {
    /// Binding strength; higher binds tighter. Unary minus binds tightest.
    fn precedence(self) -> u8 {
        match self {
            Op::LParen => 0,
            Op::Add | Op::Sub => 1,
            Op::Mul | Op::Div | Op::Rem => 2,
            Op::Neg => 3,
        }
    }

    fn binary(byte: u8) -> Option<Op> {
        Some(match byte {
            b'+' => Op::Add,
            b'-' => Op::Sub,
            b'*' => Op::Mul,
            b'/' => Op::Div,
            b'%' => Op::Rem,
            _ => return None,
        })
    }
}

/// Reusable expression evaluator. Holding the stacks across lines avoids
/// reallocating them for every expression.
#[derive(Debug, Default)]
pub struct Evaluator {
    values: Vec<i64>,
    ops: Vec<Op>,
}

impl Evaluator {
    /// Parses and evaluates one expression (without its line terminator).
    pub fn eval(&mut self, expr: &[u8]) -> Result<i64, Error> {
        self.values.clear();
        self.ops.clear();

        // Whether the parser is positioned where an operand (number, `(` or
        // unary `-`) is expected, as opposed to a binary operator or `)`.
        let mut expect_operand = true;
        let mut i = 0;

        while i < expr.len() {
            let byte = expr[i];
            if is_blank(byte) {
                i += 1;
                continue;
            }

            if expect_operand {
                match byte {
                    b'0'..=b'9' => {
                        let (value, len) = parse_number(&expr[i..])?;
                        self.values.push(value);
                        i += len;
                        expect_operand = false;
                        continue;
                    }
                    b'-' => self.ops.push(Op::Neg),
                    b'(' => self.ops.push(Op::LParen),
                    _ => return Err(Error::Syntax),
                }
            } else {
                match byte {
                    b')' => {
                        self.reduce_while(|_| true)?;
                        if self.ops.pop() != Some(Op::LParen) {
                            return Err(Error::Syntax);
                        }
                    }
                    _ => {
                        let op = Op::binary(byte).ok_or(Error::Syntax)?;
                        // Left associativity: reduce operators that bind at
                        // least as tightly before pushing this one.
                        let precedence = op.precedence();
                        self.reduce_while(|top| top.precedence() >= precedence)?;
                        self.ops.push(op);
                        expect_operand = true;
                    }
                }
            }
            i += 1;
        }

        if expect_operand {
            return Err(Error::Syntax);
        }
        self.reduce_while(|_| true)?;
        if !self.ops.is_empty() {
            // An unmatched `(` remains.
            return Err(Error::Syntax);
        }
        debug_assert_eq!(self.values.len(), 1);
        self.values.pop().ok_or(Error::Syntax)
    }

    /// Applies stacked operators, innermost first, while `pred` accepts the
    /// top one. Never crosses an open parenthesis.
    fn reduce_while(&mut self, pred: impl Fn(Op) -> bool) -> Result<(), Error> {
        while let Some(&op) = self.ops.last() {
            if op == Op::LParen || !pred(op) {
                break;
            }
            self.ops.pop();
            self.apply(op)?;
        }
        Ok(())
    }

    /// Applies `op` to the operands on top of the value stack.
    fn apply(&mut self, op: Op) -> Result<(), Error> {
        // The parser only reduces an operator once all its operands have been
        // pushed, so the value stack cannot underflow here.
        const INVARIANT: &str = "operand stack underflow";

        let rhs = self.values.pop().expect(INVARIANT);
        let result = if op == Op::Neg {
            rhs.checked_neg().ok_or(Error::Overflow)?
        } else {
            let lhs = self.values.pop().expect(INVARIANT);
            binary(op, lhs, rhs)?
        };
        self.values.push(result);
        Ok(())
    }
}

/// Evaluates a binary operator with the checked semantics of the spec.
fn binary(op: Op, lhs: i64, rhs: i64) -> Result<i64, Error> {
    let result = match op {
        Op::Add => lhs.checked_add(rhs),
        Op::Sub => lhs.checked_sub(rhs),
        Op::Mul => lhs.checked_mul(rhs),
        Op::Div | Op::Rem if rhs == 0 => return Err(Error::DivisionByZero),
        Op::Div => lhs.checked_div(rhs),
        // `i64::MIN % -1` is mathematically 0, which `wrapping_rem` yields.
        Op::Rem => Some(lhs.wrapping_rem(rhs)),
        Op::Neg | Op::LParen => unreachable!("{op:?} is not a binary operator"),
    };
    result.ok_or(Error::Overflow)
}

/// Parses the maximal run of ASCII digits at the start of `bytes` (which must
/// begin with a digit), returning its value and length.
fn parse_number(bytes: &[u8]) -> Result<(i64, usize), Error> {
    let len = bytes.iter().take_while(|b| b.is_ascii_digit()).count();
    let value = bytes[..len].iter().try_fold(0i64, |acc, &digit| {
        acc.checked_mul(10)?.checked_add(i64::from(digit - b'0'))
    });
    value.map(|value| (value, len)).ok_or(Error::Overflow)
}

fn is_blank(byte: u8) -> bool {
    byte == b' ' || byte == b'\t'
}

#[cfg(test)]
mod tests {
    use super::*;

    fn eval(expr: &str) -> Result<i64, Error> {
        Evaluator::default().eval(expr.as_bytes())
    }

    fn run_str(input: &str) -> String {
        let mut out = Vec::new();
        run(input.as_bytes(), &mut out).unwrap();
        String::from_utf8(out).unwrap()
    }

    #[test]
    fn precedence_and_associativity() {
        assert_eq!(eval("1 + 2 * 3"), Ok(7));
        assert_eq!(eval("(1 + 2) * 3"), Ok(9));
        assert_eq!(eval("1 + 2 * 3 - 4 / 2 % 3"), Ok(5));
        assert_eq!(eval("10 - 4 - 3"), Ok(3));
        assert_eq!(eval("100 / 10 / 5"), Ok(2));
        assert_eq!(eval("2 - -3 * 4"), Ok(14));
        assert_eq!(eval("-2 * 3"), Ok(-6));
    }

    #[test]
    fn division_and_remainder() {
        assert_eq!(eval("-7 / 2"), Ok(-3));
        assert_eq!(eval("-7 % 3"), Ok(-1));
        assert_eq!(eval("7 % -3"), Ok(1));
        assert_eq!(eval("1 / 0"), Err(Error::DivisionByZero));
        assert_eq!(eval("1 % (2 - 2)"), Err(Error::DivisionByZero));
        assert_eq!(eval("(-9223372036854775807 - 1) % -1"), Ok(0));
        assert_eq!(
            eval("(-9223372036854775807 - 1) / -1"),
            Err(Error::Overflow)
        );
    }

    #[test]
    fn overflow() {
        assert_eq!(eval("9223372036854775807"), Ok(i64::MAX));
        assert_eq!(eval("9223372036854775808"), Err(Error::Overflow));
        assert_eq!(eval("-9223372036854775808"), Err(Error::Overflow));
        assert_eq!(eval("-9223372036854775807 - 1"), Ok(i64::MIN));
        assert_eq!(eval("-(-9223372036854775807 - 1)"), Err(Error::Overflow));
        assert_eq!(eval("9223372036854775807 + 1"), Err(Error::Overflow));
        assert_eq!(eval("4611686018427387904 * 2"), Err(Error::Overflow));
        assert_eq!(eval("00000000000000000000000000042"), Ok(42));
    }

    #[test]
    fn syntax_errors() {
        for expr in [
            "1 +", "abc", "()", "1 2", "+1", "(1 + 2", "1 + 2)", ")(", "1 (2)", "(1)2", "1 ** 2",
            "1\r", "-",
        ] {
            assert_eq!(eval(expr), Err(Error::Syntax), "{expr:?}");
        }
    }

    #[test]
    fn deep_nesting_does_not_overflow_the_stack() {
        let depth = 1_000_000;
        let nested = format!("{}7{}", "(".repeat(depth), ")".repeat(depth));
        assert_eq!(eval(&nested), Ok(7));
        let negated = format!("{}7", "-".repeat(depth));
        assert_eq!(eval(&negated), Ok(7));
    }

    #[test]
    fn lines() {
        assert_eq!(run_str("\n  42  \n\t\n1+1\n"), "42\n2\n");
        assert_eq!(run_str("1 +\n2 * 3"), "error\n6\n");
        assert_eq!(run_str(""), "");
    }
}

//! `app lru`: LRU cache simulator. See the `lru` section of SPEC.md.
//!
//! The cache is a hash map from key to slot index plus an intrusive doubly
//! linked recency list stored in a slab (`Vec<Node>`), so every command runs
//! in O(1) expected time without per-node heap links. Keys and values are
//! handled as raw bytes: the spec restricts them to printable ASCII, so no
//! UTF-8 validation is needed.

use std::collections::HashMap;
use std::io::{self, BufRead, Write};

/// Largest capacity the spec allows; also bounds up-front allocation.
const MAX_CAPACITY: usize = 1_000_000;

/// Sentinel index meaning "no node".
const NIL: usize = usize::MAX;

/// Entry point for `app lru`: reads `input` to completion and writes the
/// result to `output`. The caller flushes `output`.
pub fn run<R: BufRead, W: Write>(mut input: R, mut output: W) -> io::Result<()> {
    let mut line = Vec::with_capacity(256);

    // Line 1: capacity. Empty input means there is nothing to simulate.
    if input.read_until(b'\n', &mut line)? == 0 {
        return Ok(());
    }
    let capacity = parse_capacity(trim_line(&line))?;
    let mut cache = LruCache::new(capacity);

    loop {
        line.clear();
        if input.read_until(b'\n', &mut line)? == 0 {
            break;
        }
        execute(&mut cache, trim_line(&line), &mut output)?;
    }
    Ok(())
}

/// Runs one command line against `cache`, writing any output it produces.
/// Lines that are not a well-formed command are ignored.
fn execute<W: Write>(cache: &mut LruCache, line: &[u8], output: &mut W) -> io::Result<()> {
    let mut tokens = line.split(|&b| b == b' ');
    let command = tokens.next().unwrap_or_default();
    let args = (tokens.next(), tokens.next(), tokens.next());

    match (command, args) {
        (b"SET", (Some(key), Some(value), None)) => cache.set(key, value),
        (b"GET", (Some(key), None, None)) => {
            let value = cache.get(key).unwrap_or(b"NULL");
            output.write_all(value)?;
            output.write_all(b"\n")?;
        }
        (b"DEL", (Some(key), None, None)) => {
            output.write_all(if cache.remove(key) { b"1\n" } else { b"0\n" })?;
        }
        (b"SIZE", (None, None, None)) => writeln!(output, "{}", cache.len())?,
        _ => {}
    }
    Ok(())
}

/// Strips the line terminator (`\n`, tolerating a preceding `\r`).
fn trim_line(line: &[u8]) -> &[u8] {
    let line = line.strip_suffix(b"\n").unwrap_or(line);
    line.strip_suffix(b"\r").unwrap_or(line)
}

fn parse_capacity(line: &[u8]) -> io::Result<usize> {
    std::str::from_utf8(line)
        .ok()
        .and_then(|s| s.trim().parse::<usize>().ok())
        .filter(|c| (1..=MAX_CAPACITY).contains(c))
        .ok_or_else(|| {
            io::Error::new(
                io::ErrorKind::InvalidData,
                format!("lru: invalid capacity {:?}", String::from_utf8_lossy(line)),
            )
        })
}

/// A slot in the recency list.
struct Node {
    key: Box<[u8]>,
    value: Box<[u8]>,
    prev: usize,
    next: usize,
}

/// A fixed-capacity least-recently-used cache over byte-string keys and values.
struct LruCache {
    capacity: usize,
    index: HashMap<Box<[u8]>, usize>,
    nodes: Vec<Node>,
    /// Slots of removed nodes, reused before the slab grows.
    free: Vec<usize>,
    /// Most recently used node.
    head: usize,
    /// Least recently used node.
    tail: usize,
}

impl LruCache {
    fn new(capacity: usize) -> Self {
        assert!(capacity > 0, "LRU capacity must be positive");
        Self {
            capacity,
            index: HashMap::with_capacity(capacity + 1),
            nodes: Vec::with_capacity(capacity),
            free: Vec::new(),
            head: NIL,
            tail: NIL,
        }
    }

    fn len(&self) -> usize {
        self.index.len()
    }

    /// Returns the value for `key`, marking it most recently used on a hit.
    fn get(&mut self, key: &[u8]) -> Option<&[u8]> {
        let slot = *self.index.get(key)?;
        self.move_to_front(slot);
        Some(&self.nodes[slot].value)
    }

    /// Inserts or overwrites `key`, making it most recently used and evicting
    /// the least recently used entry if the cache would exceed its capacity.
    fn set(&mut self, key: &[u8], value: &[u8]) {
        if let Some(&slot) = self.index.get(key) {
            let node = &mut self.nodes[slot];
            if *node.value != *value {
                node.value = value.into();
            }
            self.move_to_front(slot);
            return;
        }

        if self.len() == self.capacity {
            // Recycle the evicted node's slot and key allocation in place.
            let slot = self.tail;
            self.unlink(slot);
            let node = &mut self.nodes[slot];
            self.index.remove(&node.key);
            node.key = key.into();
            node.value = value.into();
            self.index.insert(node.key.clone(), slot);
            self.push_front(slot);
            return;
        }

        let node = Node {
            key: key.into(),
            value: value.into(),
            prev: NIL,
            next: NIL,
        };
        let slot = match self.free.pop() {
            Some(slot) => {
                self.nodes[slot] = node;
                slot
            }
            None => {
                self.nodes.push(node);
                self.nodes.len() - 1
            }
        };
        self.index.insert(key.into(), slot);
        self.push_front(slot);
    }

    /// Removes `key`, returning whether it was present.
    fn remove(&mut self, key: &[u8]) -> bool {
        let Some(slot) = self.index.remove(key) else {
            return false;
        };
        self.unlink(slot);
        let node = &mut self.nodes[slot];
        node.key = Box::default();
        node.value = Box::default();
        self.free.push(slot);
        true
    }

    fn move_to_front(&mut self, slot: usize) {
        if self.head != slot {
            self.unlink(slot);
            self.push_front(slot);
        }
    }

    fn unlink(&mut self, slot: usize) {
        let Node { prev, next, .. } = self.nodes[slot];
        match prev {
            NIL => self.head = next,
            p => self.nodes[p].next = next,
        }
        match next {
            NIL => self.tail = prev,
            n => self.nodes[n].prev = prev,
        }
    }

    fn push_front(&mut self, slot: usize) {
        let old_head = self.head;
        {
            let node = &mut self.nodes[slot];
            node.prev = NIL;
            node.next = old_head;
        }
        match old_head {
            NIL => self.tail = slot,
            h => self.nodes[h].prev = slot,
        }
        self.head = slot;
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn simulate(input: &str) -> String {
        let mut out = Vec::new();
        run(input.as_bytes(), &mut out).unwrap();
        String::from_utf8(out).unwrap()
    }

    #[test]
    fn spec_example() {
        let input = "2\nSET a 1\nSET b 2\nGET a\nSET c 3\nGET b\nSIZE\n";
        assert_eq!(simulate(input), "1\nNULL\n2\n");
    }

    #[test]
    fn overwrite_refreshes_recency() {
        let input = "2\nSET a 1\nSET b 2\nSET a 9\nSET c 3\nGET a\nGET b\nGET c";
        assert_eq!(simulate(input), "9\nNULL\n3\n");
    }

    #[test]
    fn delete_then_reuse_slots() {
        let input = "2\nSET a 1\nSET b 2\nDEL a\nDEL a\nSET c 3\nSET d 4\nGET b\nGET c\nGET d\nSIZE\n";
        assert_eq!(simulate(input), "1\n0\nNULL\n3\n4\n2\n");
    }

    #[test]
    fn capacity_one() {
        let input = "1\nSET a 1\nSET b 2\nGET a\nGET b\nDEL b\nSIZE\nSET c 3\nGET c\n";
        assert_eq!(simulate(input), "NULL\n2\n1\n0\n3\n");
    }

    #[test]
    fn empty_input_prints_nothing() {
        assert_eq!(simulate(""), "");
        assert_eq!(simulate("5\n"), "");
    }
}

//! `app`: a command-line suite of independent subcommands (see SPEC.md).
//!
//! The first argument selects a subcommand. Each subcommand lives in its own
//! module and exposes the same entry point:
//!
//! ```ignore
//! pub fn run<R: BufRead, W: Write>(input: R, output: W) -> io::Result<()>
//! ```
//!
//! `input` is locked standard input; `output` is buffered, locked standard
//! output, flushed by `main` after `run` returns.

mod calc;
mod lru;
mod wordfreq;

use std::env;
use std::io::{self, BufWriter, Write};
use std::process::ExitCode;

const USAGE: &str = "usage: app <wordfreq|lru|calc>";

fn main() -> ExitCode {
    let Some(name) = env::args_os().nth(1) else {
        eprintln!("{USAGE}");
        return ExitCode::from(2);
    };

    let input = io::stdin().lock();
    let mut output = BufWriter::with_capacity(1 << 16, io::stdout().lock());

    let result = match name.to_str() {
        Some("wordfreq") => wordfreq::run(input, &mut output),
        Some("lru") => lru::run(input, &mut output),
        Some("calc") => calc::run(input, &mut output),
        _ => {
            eprintln!("app: unknown subcommand {:?}\n{USAGE}", name.to_string_lossy());
            return ExitCode::from(2);
        }
    };

    match result.and_then(|()| output.flush()) {
        Ok(()) => ExitCode::SUCCESS,
        // A closed downstream pipe is not a failure of ours.
        Err(err) if err.kind() == io::ErrorKind::BrokenPipe => ExitCode::SUCCESS,
        Err(err) => {
            eprintln!("app: {err}");
            ExitCode::FAILURE
        }
    }
}

//! `app wordfreq`: word frequencies. See the `wordfreq` section of SPEC.md.
//!
//! Input is streamed through the reader's buffer rather than read into memory
//! whole, so memory use is bounded by the number of distinct words, not by the
//! input size. A word may straddle two buffer refills; the partial word is
//! carried over in a small scratch buffer.

use std::cmp::Ordering;
use std::collections::HashMap;
use std::io::{self, BufRead, Write};

/// Number of words printed.
const TOP_N: usize = 10;

/// Entry point for `app wordfreq`: reads `input` to completion and writes the
/// result to `output`. The caller flushes `output`.
pub fn run<R: BufRead, W: Write>(input: R, mut output: W) -> io::Result<()> {
    let counts = count_words(input)?;
    for (word, count) in top_words(&counts, TOP_N) {
        output.write_all(count.to_string().as_bytes())?;
        output.write_all(b" ")?;
        output.write_all(word)?;
        output.write_all(b"\n")?;
    }
    Ok(())
}

/// Counts every word (maximal run of ASCII letters, lowercased) in `input`.
fn count_words<R: BufRead>(mut input: R) -> io::Result<HashMap<Box<[u8]>, u64>> {
    let mut counts = WordCounts::default();
    // The lowercased word currently being read; may span buffer refills.
    let mut word = Vec::new();

    loop {
        let chunk = match input.fill_buf() {
            Ok([]) => break,
            Ok(chunk) => chunk,
            Err(err) if err.kind() == io::ErrorKind::Interrupted => continue,
            Err(err) => return Err(err),
        };
        let len = chunk.len();

        let mut rest = chunk;
        while !rest.is_empty() {
            let run = rest
                .iter()
                .position(|b| !b.is_ascii_alphabetic())
                .unwrap_or(rest.len());
            word.extend(rest[..run].iter().map(u8::to_ascii_lowercase));
            if run == rest.len() {
                // The word may continue in the next chunk.
                break;
            }
            counts.add(&word);
            word.clear();

            let sep = rest[run..]
                .iter()
                .position(u8::is_ascii_alphabetic)
                .unwrap_or(rest.len() - run);
            rest = &rest[run + sep..];
        }

        input.consume(len);
    }
    counts.add(&word);

    Ok(counts.0)
}

/// Word counts keyed by lowercased word bytes.
#[derive(Default)]
struct WordCounts(HashMap<Box<[u8]>, u64>);

impl WordCounts {
    /// Records one occurrence of `word`; empty words are ignored. Allocates
    /// only the first time a word is seen.
    fn add(&mut self, word: &[u8]) {
        if word.is_empty() {
            return;
        }
        match self.0.get_mut(word) {
            Some(count) => *count += 1,
            None => {
                self.0.insert(word.into(), 1);
            }
        }
    }
}

/// Returns up to `n` entries of `counts`, ordered by count descending, then
/// word ascending (byte order).
fn top_words(counts: &HashMap<Box<[u8]>, u64>, n: usize) -> Vec<(&[u8], u64)> {
    fn rank(a: &(&[u8], u64), b: &(&[u8], u64)) -> Ordering {
        b.1.cmp(&a.1).then_with(|| a.0.cmp(b.0))
    }

    if n == 0 {
        return Vec::new();
    }
    let mut entries: Vec<(&[u8], u64)> =
        counts.iter().map(|(word, &count)| (&**word, count)).collect();
    if entries.len() > n {
        entries.select_nth_unstable_by(n - 1, rank);
        entries.truncate(n);
    }
    entries.sort_unstable_by(rank);
    entries
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::io::BufReader;

    fn wordfreq(input: &[u8]) -> String {
        let mut out = Vec::new();
        run(input, &mut out).unwrap();
        String::from_utf8(out).unwrap()
    }

    #[test]
    fn spec_example() {
        assert_eq!(
            wordfreq(b"The cat and the hat."),
            "2 the\n1 and\n1 cat\n1 hat\n"
        );
    }

    #[test]
    fn empty_and_wordless_input_prints_nothing() {
        assert_eq!(wordfreq(b""), "");
        assert_eq!(wordfreq(b"123 _'!? \n\t"), "");
    }

    #[test]
    fn non_letters_separate_words() {
        assert_eq!(
            wordfreq(b"don't stop_me 4now, now-NOW"),
            "3 now\n1 don\n1 me\n1 stop\n1 t\n"
        );
    }

    #[test]
    fn high_and_invalid_utf8_bytes_are_separators() {
        assert_eq!(wordfreq(b"caf\xc3\xa9\xffcaf\x80X"), "2 caf\n1 x\n");
    }

    #[test]
    fn at_most_ten_lines_with_ties_by_word() {
        let input = b"zeta eta theta iota kappa lambda mu nu xi omicron pi rho alpha beta alpha";
        assert_eq!(
            wordfreq(input),
            "2 alpha\n1 beta\n1 eta\n1 iota\n1 kappa\n1 lambda\n1 mu\n1 nu\n1 omicron\n1 pi\n"
        );
    }

    #[test]
    fn words_spanning_buffer_refills() {
        let input: &[u8] = b"abcdefgh ABCDEFGH abc.defgh";
        let mut out = Vec::new();
        run(BufReader::with_capacity(3, input), &mut out).unwrap();
        assert_eq!(
            String::from_utf8(out).unwrap(),
            "2 abcdefgh\n1 abc\n1 defgh\n"
        );
    }
}
